Definition sr_st (pc : Z) (ra sp gp tp t0 t1 t2 : word) (res b n pos it lst outend : Z) (a3v a6v a7 : word)
    (s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state :=
  MS (mkR ra sp gp tp t0 t1 t2 (wz res) (wz n)
          (wz (res + 16)) (wz it) (wz (b + 8)) a3v (wz outend) (wz lst) a6v a7
          (wz (res + 8)) (wz pos) (wz b) (wz (b + 40)) (Z_to_bv 64 2147450880) s7 s8 s9 s10 s11 t3 t4 t5 t6)
     F (Z_to_bv 64 pc) fc None m (seg_rom asegs).

Definition sr_at (pc : Z) (ra sp gp tp t0 t1 t2 : word) (res b n pos it lst outend : Z) (a3v a6v a7 : word)
    (s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state -> Prop :=
  fun ms' => ms' = sr_st pc ra sp gp tp t0 t1 t2 res b n pos it lst outend a3v a6v a7 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m.

Definition sr_atx (pc : Z) (ra sp gp tp t0 t1 t2 : word) (res b n pos it lst outend : Z) (a7 : word)
    (s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a3v a6v, ms' = sr_st pc ra sp gp tp t0 t1 t2 res b n pos it lst outend a3v a6v a7 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m.
