Lemma sr_skip : forall (R D T : list mbe) (m : mem) (b insz res n outend : Z) (es : list mbe) (ls : LS) (a3v a6v a7 : word)
    (ra sp gp tp t0 t1 t2 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) fc,
  dl_ok (b + 8) (map fst es) ls -> ALSCells m ls -> AMBElems m es -> mb_addr_ok b es -> AMBShad m es ->
  es = D ++ R ++ T -> R <> [] -> T <> [] ->
  mb_cap (D ++ R) <= insz -> insz < 2^64 -> 0 <= mb_cap D ->
  mem_inv asegs m ->
  evt asegs (sr_at P_A_SR_LOOP1_END ra sp gp tp t0 t1 t2 res b n (insz - mb_cap (D ++ R)) (fst (hd (0,0) T))
                   (mb_lasta b es) outend (wz (mb_lasts R)) (Z_to_bv 64 0) a7 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m)
    (sr_st P_A_SR_LOOP1 ra sp gp tp t0 t1 t2 res b n (insz - mb_cap D) (fst (hd (0,0) R)) (mb_lasta b es) outend a3v a6v a7
           s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m).
