  Local Ltac rchk g :=
    lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
      lazymatch goal with MUx : munch _ _ mx |- _ =>
        let RD := fresh "RD" in
        pose proof (accessible_read0_sr mx res 40 g (accessible_transport_awin _ _ _ _ _ RACC MUx sr_FW)
                      ltac:(clear; lia) ltac:(clear - RAL; Z.div_mod_to_equations; lia) ltac:(clear; lia)) as RD
      end end.
  Local Ltac echk IN xe se X16 XB g :=
    lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
      lazymatch goal with MUx : munch _ _ mx, WMx : wmono _ _ mx |- _ =>
        let RD := fresh "RD" in
        pose proof (AMBraw_elem_rd0 _ _ mx _ _ _ _ _ _ xe se g MID MUx WMx sr_FWM IN
                      ltac:(clear; lia) ltac:(clear - XB; lia) ltac:(clear - X16; Z.div_mod_to_equations; lia)) as RD
      end end.

