(* [comment removed for export] *)
Lemma mb_put_es_ne : forall es insz n x, mb_ok es insz -> 1 <= n -> mb_put_es es insz n x <> [].
Proof.
  intros es insz n x OK N1. unfold mb_put_es. destruct (mb_need es insz n) eqn:ND; [destruct es; discriminate|].
  intros E. rewrite E in ND. unfold mb_need in ND. cbn in ND. destruct OK as (E0 & _). rewrite (E0 E) in ND. apply Z.ltb_ge in ND. lia.
Qed.

Lemma mb_mid_outend_pos : forall es insz n, mb_ok es insz -> 1 <= n -> 1 <= mb_mid_outend es insz n.
Proof.
  intros es insz n OK N1. pose proof (mb_ok_bounds _ _ OK) as [B1 B2]. unfold mb_mid_outend, mb_outpos.
  destruct (mb_need es insz n) eqn:ND; [unfold mb_need in ND; apply Z.ltb_lt in ND; lia|].
  destruct (mb_full es insz); lia.
Qed.

Section SRP.
  Hypothesis MEMSET : asan_memset_stmt.

(* [comment removed for export] *)
Lemma sr_prefix : forall (Q : machine_state -> Prop) (res b : Z) (es : list mbe) (insz n x lo : Z) (rj : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  AMBmid m b es insz n x -> mb_ok es insz -> 1 <= n -> insz + n <= 2^30 ->
  rw_cells asegs m res [CB 40 rj] ->
  stk asegs m lo (bv_unsigned sp) -> lo + MB_SR_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv asegs m ->
  ACONST m ->
  aapp res 40 -> res mod 8 = 0 -> accessible m res 40 -> shvis m res (res + 40) ->
  mb_off b (mb_put_es es insz n x) res 40 ->
  (forall (m1 : mem) (z16 j16 : list byte) (rax y0 y1 y2 a3v a6v a7' y3 y4 y5 y6 : word),
     munch [(lo, bv_unsigned sp); (res, res + 40)]%Z m m1 -> wmono asegs m m1 -> mem_inv asegs m1 ->
     sr_frame ra sp s0 s1 s2 s3 s4 s5 s6 m1 -> stk asegs m1 lo (bv_unsigned sp + -64) ->
     rw_cells asegs m1 res [C8 (Z_to_bv 64 b)] ->
     rw_cells asegs m1 (res + 8) [CB 16 z16] -> rw_cells asegs m1 (res + 24) [CB 16 j16] ->
     evt asegs Q (sr_st 0xbedf8 rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp y0 y1 y2 res b n (0 + insz)
                        (lhead (b + 8) (map fst (mb_put_es es insz n x))) (mb_lasta b (mb_put_es es insz n x))
                        (mb_mid_outend es insz n) a3v a6v a7' s7 s8 s9 s10 s11 y3 y4 y5 y6 F fc m1)) ->
  evt asegs Q
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz res) (wz b) (wz insz) (wz n) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
